// Measure TTFB using the Performance Navigation Timing API
const [navigationEntry] = performance.getEntriesByType('navigation') as PerformanceNavigationTiming[];

if (navigationEntry) {
  // Backend processing & network duration from request to first byte
  const ttfb = navigationEntry.responseStart - navigationEntry.requestStart;

  // Total TTFB from navigation initiation
  const totalTtfb = navigationEntry.responseStart - navigationEntry.startTime;

  console.log(`TTFB (Request to First Byte): ${ttfb.toFixed(2)} ms`);
  console.log(`Total TTFB (Start to First Byte): ${totalTtfb.toFixed(2)} ms`);
}
